private AutoDetectReader(InputStream stream, Charset charset) throws IOException {
    super(new InputStreamReader(stream, charset));
    this.charset = charset;
    // TIKA-240: Drop the BOM if present
    mark(1);
    if (read() != '\ufeff') {
        // zero-width no-break space
        reset();
    }
}
